import { useState } from "react";
import "./Sidebar.css";

export default function Sidebar() {
  const [isOpen, setIsOpen] = useState(false);

  return (
    <div className={`sidebar ${isOpen ? "open" : "closed"}`}>
		<div>
			<button className="toggle-btn" onClick={() => setIsOpen(!isOpen)}>
				☰
			</button>

			<ul className="menu">
				<li>
				{isOpen && <span className="text"><a>Cadastrar</a></span>}
				</li>

				<li>
				{isOpen && <span className="text">Mapa</span>}
				</li>

				<li>
				{isOpen && <span className="text">Configurações</span>}
				</li>
			</ul>
      	</div>
	  <div>
		{isOpen && (
			<form
				className="cadastro-form"
				onSubmit={async (e) => {
					e.preventDefault();
					const form = e.target;
					const data = {
						nome: form.nome.value,
						endereco: {
							logradouro: form.logradouro.value,
							numero: form.numero.value,
							bairro: form.bairro.value,
							cidade: form.cidade.value,
							estado: form.estado.value,
							cep: form.cep.value,
						},
					};
					await fetch("https://sua-url.com/api/cadastrar", {
						method: "POST",
						headers: { "Content-Type": "application/json" },
						body: JSON.stringify(data),
					});
					form.reset();
				}}
			>
				<label>
					Nome:
					<input name="nome" type="text" required />
				</label>
				<label>
					Logradouro:
					<input name="logradouro" type="text" required />
				</label>
				<label>
					Número:
					<input name="numero" type="text" required />
				</label>
				<label>
					Bairro:
					<input name="bairro" type="text" required />
				</label>
				<label>
					Cidade:
					<input name="cidade" type="text" required />
				</label>
				<label>
					Estado:
					<input name="estado" type="text" required />
				</label>
				<label>
					CEP:
					<input name="cep" type="text" />
				</label>
				<button type="submit">Cadastrar</button>
			</form>
		)}

	  </div>
    </div>
  );
}
